```csharp
string cs = "Server=.;Database=Shop;Trusted_Connection=True;";
using (var conn = new SqlConnection(cs))
{
    conn.Open();
    using (var cmd = new SqlCommand("SELECT Id, Name FROM Users WHERE City = @city", conn))
    {
        cmd.Parameters.AddWithValue("@city", "London"); // parameterized = safe
        using (var reader = cmd.ExecuteReader())
        {
